$method=$_SERVER['REQUEST_METHOD']??'GET';$path=trim(parse_url($_SERVER['REQUEST_URI']??'',PHP_URL_PATH)??'','/');$parts=explode('/',$path);$api=array_search('api',$parts,true);$parts=$api===false?[]:array_slice($parts,$api+1);
