function publicEvent(string $slug): ?array {$q=db()->prepare('SELECT id,name,slug,city,event_date,distance,category,status,appeal_minutes,appeal_ends_at,event_type,show_general FROM events WHERE slug=? AND is_published=1');$q->execute([$slug]);return $q->fetch()?:null;}
